import styles from "./lifeStats.module.css";

type Axis = "action" | "intellect" | "social" | "recovery" | "luck" | "hp";
type CoreAxis = Exclude<Axis, "hp">;
type Weights = Partial<Record<Axis, number>>;

type Question = {
  text: string;
  tag: string;
  weights: Weights;
  reverse?: boolean;
};

const questions: Question[] = [
