  { text: "ここ1週間、寝たり休んだりするとちゃんと回復した感覚がある", tag: "回復ポイント", weights: { hp: 1.5, recovery: .5 } },
  { text: "何もない日でも、結果的に『なんかあった日』になりやすい", tag: "ランダムイベント", weights: { luck: 1.4 } },
  { text: "今の自分には、まだ“もう一戦”できる余力がある", tag: "残りHP", weights: { hp: 1.7, action: .2 } },
