    tactic: "COMMITMENT",
    eyebrow: "FINAL ROUND / 最終値下げ",
    ask: "『あと1本だけ』を、本当に『次の1本で終了』に変える？",
    sub: "ゼロにしなくていい。終わる場所だけ先に決める。",
    choices: [
      {
        label: "次の1本で終了",
        reply: "交渉成立。次は再発防止の一手だけ決めます。",
        action: "plan",
        tone: "deal",
        delta: 26,
      },
      {
        label: "区切りは決めない",
        reply: "今回は強い。では『次に開く前の一手』だけ残して終わります。",
        action: "plan",
