  padding: 0 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.planChoices span {
  font-weight: 850;
}

.planChoices i {
  color: #d8ff52;
  font-style: normal;
  font-size: 10px;
  font-weight: 900;
  white-space: nowrap;
}

.resultStamp {
  width: fit-content;
  padding: 6px 9px;
  background: #d8ff52;
  color: #0c0f0c;
}

.drawStamp {
  width: fit-content;
  padding: 6px 9px;
  background: #ff5d47;
  color: #100907;
}

.resultLead strong {
  color: #f0f3ef;
}

.resultCard {
  margin-top: 24px;
  border: 1px solid #d8ff52;
  padding: 17px;
}

.resultCard span,
.handbook > p {
  display: block;
  color: #80878c;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: .12em;
}

.resultCard strong {
  display: block;
  margin-top: 7px;
  color: #d8ff52;
  font-size: 16px;
  line-height: 1.5;
}

.handbook {
  margin-top: 20px;
}

.handbook > p {
  margin: 0 0 9px;
}

.handbook > div {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.handbook span {
  border: 1px solid #30363a;
  padding: 6px 8px;
  color: #979ea3;
  font-size: 10px;
}

.resultStats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: 22px 0;
  border-top: 1px solid #30363a;
  border-bottom: 1px solid #30363a;
}

.resultStats span {
  padding: 13px 8px;
  color: #858c91;
  font-size: 10px;
  text-align: center;
  border-right: 1px solid #30363a;
}

.resultStats span:last-child {
  border-right: 0;
}

.resultStats b {
  display: block;
  margin-top: 4px;
  color: #f2f4ef;
  font-size: 17px;
}

@keyframes rise {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (max-width: 480px) {
  .page {
    padding-top: 14px;
  }

  .intro {
    justify-content: flex-start;
    padding-top: 58px;
  }

  .lead br {
    display: none;
  }

  .rules span {
    font-size: 11px;
  }

  .gameHeader > div {
    gap: 7px;
  }

  .gameHeader strong {
    font-size: 12px;
  }

  .resultStats span {
    padding-inline: 4px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .meterFill,
  .countdownFill,
  .choice,
  .reply {
    transition: none;
    animation: none;
  }
}
